 43	### `LoadOrderKeeper.Coordinators.FileMonitoringCoordinator`
 44	
 45	```csharp
 46	public sealed class FileMonitoringCoordinator : CoordinatorBase
 47	{
 48	    // Properties
 49	    public bool PluginsFileChangedExternally { get; }
 50	    public int ChangeCount { get; }
 51	    public string SortingRecommendationMessage { get; }
 52	    public bool SortingRecommendationActive { get; }
