 59	    public event EventHandler<ChangeDetectedEventArgs>? ChangeDetected;
 60	    public event EventHandler<SortingRecommendationChangedEventArgs>? SortingRecommendationChanged;
 61	    public event EventHandler<SteamWarningChangedEventArgs>? SteamWarningChanged;
